import catalog from "./catalog.json";

// Generated by `npm run themes:fetch` (scripts/fetch-themes.mjs).
export type BoardTheme = { id: string; name: string; file: string; light: string; dark: string };
export type PieceSet = { id: string; name: string };

export const BOARDS: BoardTheme[] = catalog.boards;
export const PIECE_SETS: PieceSet[] = catalog.pieces;

export const DEFAULT_BOARD = "green";
export const DEFAULT_PIECES = "neo";

export const PIECE_CODES = ["wp", "wn", "wb", "wr", "wq", "wk", "bp", "bn", "bb", "br", "bq", "bk"] as const;

export const pieceImage = (set: string, code: string) => `/themes/pieces/${set}/${code}.png`;
export const boardImage = (board: BoardTheme) => `/themes/boards/${board.file}`;
export const boardThumb = (board: BoardTheme) => `/themes/boards/thumbs/${board.file}`;
